 import { useSettings } from '../hooks/useSettings'

export default function CommentSection({ postId, comments, onRefresh, currentUser }) {
    const { settings } = useSettings()
    // ... rest of your code

    const allowComments = settings?.allow_comments !== false
    const maxCommentLength = settings?.max_comment_length || 1000
    const moderationMode = settings?.comment_moderation || 'none'
    const autoModeration = settings?.auto_moderation_enabled || false

    const handleComment = async (e) => {
        e.preventDefault()
        
        // ✅ Check if comments are allowed
        if (!allowComments) {
            showToast('Comments are currently disabled', 'warning')
            return
        }

        // ✅ Check max comment length
        if (newComment.trim().length > maxCommentLength) {
            showToast(`Comment must be ${maxCommentLength} characters or less`, 'warning')
            return
        }

        // ✅ Auto-moderation check
        if (autoModeration) {
            // Simple spam detection - check for repeated characters, links, etc.
            const spamScore = checkSpamScore(newComment)
            if (spamScore > 0.7) {
                showToast('Your comment was flagged for review', 'warning')
                // You could store the comment as pending review
                // For now, just return
                return
            }
        }

        // ... rest of comment submission logic
    }

    // Simple spam detection function
    const checkSpamScore = (text) => {
        let score = 0
        // Check for repeated characters
        if (/(.)\1{5,}/.test(text)) score += 0.3
        // Check for excessive capitalization
        if ((text.match(/[A-Z]/g) || []).length > text.length * 0.5) score += 0.2
        // Check for common spam keywords
        const spamKeywords = ['free money', 'click here', 'win now', 'casino']
        spamKeywords.forEach(keyword => {
            if (text.toLowerCase().includes(keyword)) score += 0.2
        })
        return Math.min(score, 1)
    }

    // ✅ Only show comment input if comments are allowed
    if (!allowComments) {
        return (
            <div className="text-center py-4 text-gray-400">
                Comments are currently disabled
            </div>
        )
    }

    // ... rest of component
}
